#!/usr/bin/env python3
from pathlib import Path
import base64

FILES = {
    Path("App/AppModel.swift"): b'',
    Path("Shared/OLCBridge.m"): b'',
}

for path, payload in FILES.items():
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(base64.b64decode(payload))
    print(f"Replaced {path} ({path.stat().st_size} bytes)")

swift = Path("App/AppModel.swift").read_text(encoding="utf-8")
bridge = Path("Shared/OLCBridge.m").read_text(encoding="utf-8")

checks = {
    "old MainActor access": "self.profile.provider" not in swift,
    "Swift local snapshot": "let provider = profile.provider" in swift,
    "MobileCheck out parameter": "BOOL succeeded = MobileCheck" in bridge and "&elapsed" in bridge,
    "MobilePing out parameter": "BOOL succeeded = MobilePing" in bridge,
    "NSDate syntax": "[[NSDate date] description]" in bridge,
}

failed = [name for name, ok in checks.items() if not ok]
if failed:
    raise SystemExit("Patch verification failed: " + ", ".join(failed))

print("iOS source files replaced and verified.")
